<?php
declare(strict_types=1);
// All new writes share one short transaction mutex. No original row is reassigned by name.
final class WebError extends RuntimeException {public function __construct(string $message,public int $status=400){parent::__construct($message);}}
function tfRequire(mixed $condition,string $message,int $status=400):void{if(!$condition)throw new WebError($message,$status);}
function tfQuery(mysqli $db,string $sql,array $args=[]):array{$s=$db->prepare($sql);if($args)$s->bind_param(str_repeat('s',count($args)),...$args);$s->execute();$out=$s->get_result();$rows=$out?$out->fetch_all(MYSQLI_ASSOC):[];$s->close();return $rows;}
function tfNow():DateTimeImmutable{$test=getenv('TF_SSO_TEST_NOW');tfRequire(!$test||getenv('TF_SSO_TEST_MODE')==='1','TEST_CLOCK_FORBIDDEN',503);return (new DateTimeImmutable($test?:'now',new DateTimeZone('Europe/Madrid')))->setTimezone(new DateTimeZone('Europe/Madrid'));}
function tfWeek(string $date):array{$d=DateTimeImmutable::createFromFormat('!Y-m-d',$date,new DateTimeZone('Europe/Madrid'));tfRequire($d&&$d->format('Y-m-d')===$date,'INVALID_DATE');$start=$d->modify('-'.((int)$d->format('N')-1).' days');return [$start->format('Y-m-d'),$start->modify('+6 days')->format('Y-m-d')];}
function tfAtomic(mysqli $db,callable $work):mixed{for($i=0;$i<3;$i++){try{$db->begin_transaction();tfQuery($db,'SELECT id FROM tf_mutex WHERE id=1 FOR UPDATE');$out=$work();$db->commit();return $out;}catch(Throwable $e){$db->rollback();if($e instanceof mysqli_sql_exception&&in_array($e->getCode(),[1205,1213],true)&&$i<2)continue;throw $e;}}throw new WebError('TEMPORARY_FAILURE',503);}
function tfPerson(mysqli $db,int $id):array{$p=tfQuery($db,'SELECT * FROM tf_people WHERE id=? AND active=1',[$id])[0]??null;tfRequire($p,'ACCESS_DENIED',403);return $p;}
function tfAllowed(mysqli $db,string $principal,int $person):array{tfRequire(tfQuery($db,'SELECT person_id FROM tf_permissions WHERE principal=? AND person_id=?',[$principal,$person]),'ACCESS_DENIED',403);return tfPerson($db,$person);}
function tfJson(array $data,int $status=200):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store, private');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);exit;}
function tfCookie(string $value,int $expires):void{setcookie('TF_RESERVAS',$value,['expires'=>$expires,'path'=>'/reservas/','secure'=>true,'httponly'=>true,'samesite'=>'Lax']);}
function tfSession(mysqli $db):?array{$token=(string)($_COOKIE['TF_RESERVAS']??'');if(!preg_match('/^[a-f0-9]{64}$/',$token))return null;$r=tfQuery($db,'SELECT s.* FROM tf_sessions s JOIN tf_people p ON p.id=s.person_id JOIN tf_permissions a ON a.principal=s.principal AND a.person_id=s.person_id WHERE s.token_hash=? AND s.expires_at>? AND s.epoch=p.session_epoch AND p.active=1',[hash('sha256',$token),time()])[0]??null;return $r;}
function tfCsrf():string{return hash_hmac('sha256','topfitness-reservas-csrf',(string)($_COOKIE['TF_RESERVAS']??''));}
function tfCheckCsrf():void{tfRequire(hash_equals(tfCsrf(),(string)($_SERVER['HTTP_X_CSRF_TOKEN']??'')),'CSRF_REQUIRED',403);tfRequire(($_SERVER['HTTP_ORIGIN']??'')===getenv('TF_PUBLIC_ORIGIN'),'ORIGIN_REQUIRED',403);}
function tfMint(mysqli $db,string $principal,int $person):array{$p=tfAllowed($db,$principal,$person);$token=bin2hex(random_bytes(32));tfQuery($db,'INSERT INTO tf_links VALUES(?,?,?,?,NULL,?)',[hash('sha256',$token),$principal,$person,time()+300,$p['session_epoch']]);return ['url'=>'https://whatsapp.gimnasio.example/reservas/entrar.php?t='.$token,'expires_in'=>300];}
function tfRedeem(mysqli $db,string $token):array{tfRequire(preg_match('/^[a-f0-9]{64}$/',$token),'LINK_INVALID',401);return tfAtomic($db,function()use($db,$token){$r=tfQuery($db,'SELECT * FROM tf_links WHERE token_hash=? FOR UPDATE',[hash('sha256',$token)])[0]??null;tfRequire($r&&$r['used_at']===null&&(int)$r['expires_at']>time(),'LINK_INVALID',401);$p=tfAllowed($db,$r['principal'],(int)$r['person_id']);tfRequire((int)$p['session_epoch']===(int)$r['epoch'],'LINK_INVALID',401);tfQuery($db,'UPDATE tf_links SET used_at=? WHERE token_hash=?',[time(),$r['token_hash']]);$session=bin2hex(random_bytes(32));$expires=time()+3600;tfQuery($db,'INSERT INTO tf_sessions VALUES(?,?,?,?,?)',[hash('sha256',$session),$r['principal'],$p['id'],$expires,$p['session_epoch']]);return ['cookie'=>$session,'expires'=>$expires];});}
function tfQuota(mysqli $db,int $person,string $date,int $except=0):array{[$from,$until]=tfWeek($date);$n=(int)tfQuery($db,"SELECT COUNT(*) n FROM tf_bookings WHERE person_id=? AND fecha BETWEEN ? AND ? AND estado IN ('RESERVED','WAITLIST') AND id<>? AND NOT EXISTS (SELECT 1 FROM clases_canceladas cc WHERE cc.horario_id=tf_bookings.horario_id AND cc.fecha=tf_bookings.fecha)",[$person,$from,$until,$except])[0]['n'];return ['used'=>$n,'limit'=>10,'from'=>$from,'until'=>$until];}
function tfPhoneKey(string $phone):string{$n=preg_replace('/\D/','',$phone);if(str_starts_with($n,'00'))$n=substr($n,2);return strlen($n)===9?'34'.$n:$n;}
function tfPhoneSql(string $field):string{tfRequire(in_array($field,['x.telefono','telefono'],true),'INVALID_COLUMN');$e=$field;foreach([' ', '+','-','(',')','.'] as $char)$e="REPLACE($e,'$char','')";$e="IF(LEFT($e,2)='00',SUBSTRING($e,3),$e)";return "IF(LENGTH($e)=9,CONCAT('34',$e),$e)";}
function tfLegacyPending(mysqli $db,array $p,string $date):bool{[$from,$until]=tfWeek($date);$phone=tfPhoneSql('x.telefono');foreach(['inscripciones'=>'reservation_id','inscripciones_cola'=>'wait_id'] as $table=>$column){if(tfQuery($db,"SELECT x.id FROM $table x LEFT JOIN tf_bookings b ON b.$column=x.id WHERE b.id IS NULL AND x.fecha BETWEEN ? AND ? AND $phone=? LIMIT 1",[$from,$until,tfPhoneKey($p['telefono'])]))return true;}return false;}
function tfSchedule(mysqli $db,int $id,string $date):array{tfWeek($date);$now=tfNow();$d=new DateTimeImmutable($date,new DateTimeZone('Europe/Madrid'));tfRequire($d>=$now->setTime(0,0)&&$d<=$now->setTime(0,0)->modify('+5 days'),'DATE_OUTSIDE_WINDOW');$h=tfQuery($db,'SELECT id,clase,dia,hora,limite FROM horarios WHERE id=?',[$id])[0]??null;tfRequire($h,'SCHEDULE_NOT_FOUND');tfRequire(!tfQuery($db,'SELECT id FROM clases_canceladas WHERE horario_id=? AND fecha=?',[$id,$date]),'SESSION_CANCELLED',409);$days=['domingo','lunes','martes','miercoles','jueves','viernes','sabado'];tfRequire($h['dia']===$days[(int)$d->format('w')],'WRONG_WEEKDAY');tfRequire(preg_match('/^(\d{2}):(\d{2})-(\d{2}):(\d{2})$/',$h['hora'])&&substr($h['hora'],0,5)<substr($h['hora'],6,5),'INVALID_SCHEDULE');tfRequire(new DateTimeImmutable($date.' '.substr($h['hora'],0,5),new DateTimeZone('Europe/Madrid'))>$now,'SESSION_STARTED');$h['id']=(int)$h['id'];$h['limite']=(int)$h['limite'];$h['fecha']=$date;$occupied=(int)tfQuery($db,'SELECT COUNT(*) n FROM inscripciones WHERE horario_id=? AND fecha=?',[$id,$date])[0]['n']+tfHeld($db,$id,$date);$h['disponibles']=max(0,$h['limite']-$occupied);return $h;}
function tfDescribe(mysqli $db,int $id):array{$b=tfQuery($db,'SELECT b.*,h.clase,h.hora,p.nombre FROM tf_bookings b JOIN horarios h ON h.id=b.horario_id JOIN tf_people p ON p.id=b.person_id WHERE b.id=?',[$id])[0]??null;tfRequire($b,'BOOKING_NOT_FOUND',404);$b['persona_id']=(int)$b['person_id'];foreach(['id','horario_id','version'] as $key)$b[$key]=(int)$b[$key];$b['posicion']=0;if($b['estado']==='WAITLIST')$b['posicion']=(int)tfQuery($db,'SELECT COUNT(*) n FROM inscripciones_cola WHERE horario_id=? AND fecha=? AND (creado_en,id)<=(SELECT creado_en,id FROM inscripciones_cola WHERE id=?)',[$b['horario_id'],$b['fecha'],$b['wait_id']])[0]['n'];unset($b['reservation_id'],$b['wait_id']);return $b;}
function tfReserve(mysqli $db,int $person,int $schedule,string $date,bool $wait,int $replace=0):array{
 $p=tfPerson($db,$person);$existing=tfQuery($db,"SELECT id FROM tf_bookings WHERE person_id=? AND horario_id=? AND fecha=? AND estado IN ('RESERVED','WAITLIST')",[$person,$schedule,$date]);if($existing)return tfDescribe($db,(int)$existing[0]['id']);
 $h=tfSchedule($db,$schedule,$date);tfRequire($h['limite']>0,'INVALID_CAPACITY');tfRequire(!tfLegacyPending($db,$p,$date),'IDENTITY_REVIEW_REQUIRED',409);$q=tfQuota($db,$person,$date,$replace);tfRequire($q['used']<10,'WEEKLY_PERSON_LIMIT',409);
 // Previous daily/future limits remain in addition to the new weekly quota.
 $phoneIds=array_column(tfQuery($db,'SELECT id FROM tf_people WHERE telefono=?',[$p['telefono']]),'id');$marks=implode(',',array_fill(0,count($phoneIds),'?'));
 $future=tfQuery($db,"SELECT b.fecha FROM tf_bookings b JOIN horarios h ON h.id=b.horario_id WHERE b.person_id IN ($marks) AND b.estado IN ('RESERVED','WAITLIST') AND b.id<>? AND CONCAT(b.fecha,' ',LEFT(h.hora,5))>? AND NOT EXISTS (SELECT 1 FROM clases_canceladas cc WHERE cc.horario_id=b.horario_id AND cc.fecha=b.fecha)",array_merge($phoneIds,[$replace,tfNow()->format('Y-m-d H:i')]));
 tfRequire(count($future)<5,'FUTURE_PHONE_LIMIT',409);tfRequire(count(array_filter($future,fn($r)=>$r['fecha']===$date))<3,'DAILY_PHONE_LIMIT',409);
 $state=$h['disponibles']>0?'RESERVED':'WAITLIST';tfRequire($state==='RESERVED'||$wait,'WAITLIST_CONFIRMATION_REQUIRED',409);
 $table=$state==='RESERVED'?'inscripciones':'inscripciones_cola';
 // A waitlist entry belongs to a dated session, never to every week of this schedule.
 if($state==='WAITLIST'){tfRequire(!tfQuery($db,'SELECT id FROM inscripciones_cola WHERE horario_id=? AND telefono=? AND fecha=?',[$schedule,$p['telefono'],$date]),'WAITLIST_ALREADY_EXISTS',409);if(tfSessionMode($db,$schedule,$date)==='OFFERS')tfRequire(tfPersonHasConfirmedPush($db,$person),'WAITLIST_REQUIRES_NOTICES',409);}
 tfQuery($db,"INSERT INTO $table(nombre,telefono,horario_id,fecha,creado_en) VALUES(?,?,?,?,NOW())",[$p['nombre'],$p['telefono'],$schedule,$date]);$raw=$db->insert_id;
 tfQuery($db,'INSERT INTO tf_bookings(person_id,horario_id,fecha,estado,reservation_id,wait_id) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE estado=VALUES(estado),reservation_id=VALUES(reservation_id),wait_id=VALUES(wait_id),version=version+1',[$person,$schedule,$date,$state,$state==='RESERVED'?$raw:null,$state==='WAITLIST'?$raw:null]);
 $id=(int)tfQuery($db,'SELECT id FROM tf_bookings WHERE person_id=? AND horario_id=? AND fecha=?',[$person,$schedule,$date])[0]['id'];return tfDescribe($db,$id);
}
function tfPromote(mysqli $db,int $schedule,string $date):void{
 if(!tfLegacyPromotionAllowed($db,$schedule,$date))return;   // en modo OFERTAS promueve el servicio de ofertas, nunca esta ruta
 try{tfSchedule($db,$schedule,$date);}catch(WebError $e){return;}
 $h=tfQuery($db,'SELECT limite FROM horarios WHERE id=?',[$schedule])[0]??null;if(!$h||(int)$h['limite']<=0)return;
 $count=(int)tfQuery($db,'SELECT COUNT(*) n FROM inscripciones WHERE horario_id=? AND fecha=?',[$schedule,$date])[0]['n'];if($count>=(int)$h['limite'])return;
 $w=tfQuery($db,'SELECT w.*,b.id booking_id,b.person_id FROM inscripciones_cola w LEFT JOIN tf_bookings b ON b.wait_id=w.id WHERE w.horario_id=? AND w.fecha=? ORDER BY w.creado_en,w.id LIMIT 1',[$schedule,$date])[0]??null;
 // Never guess the owner of an old queue entry or skip them silently.
 if(!$w||!$w['booking_id'])return;
 $p=tfPerson($db,(int)$w['person_id']);if(tfQuota($db,(int)$p['id'],$date)['used']>10)return;
 tfQuery($db,'INSERT INTO inscripciones(nombre,telefono,horario_id,fecha,creado_en) VALUES(?,?,?,?,NOW())',[$p['nombre'],$p['telefono'],$schedule,$date]);$raw=$db->insert_id;
 tfQuery($db,'UPDATE tf_bookings SET estado=\'RESERVED\',reservation_id=?,wait_id=NULL,version=version+1 WHERE id=?',[$raw,$w['booking_id']]);tfQuery($db,'DELETE FROM inscripciones_cola WHERE id=?',[$w['id']]);
}
function tfCancel(mysqli $db,int $person,int $id,?int $version=null):array{$b=tfDescribe($db,$id);tfRequire($b['persona_id']===$person,'ACCESS_DENIED',403);tfRequire($version===null||$b['version']===$version,'STALE_ACTION',409);if($b['estado']==='CANCELLED')return $b;$raw=tfQuery($db,'SELECT reservation_id,wait_id FROM tf_bookings WHERE id=?',[$id])[0];$table=$b['estado']==='RESERVED'?'inscripciones':'inscripciones_cola';$rawId=$b['estado']==='RESERVED'?$raw['reservation_id']:$raw['wait_id'];tfQuery($db,"DELETE FROM $table WHERE id=?",[$rawId]);tfQuery($db,"UPDATE tf_bookings SET estado='CANCELLED',reservation_id=NULL,wait_id=NULL,version=version+1 WHERE id=?",[$id]);if($b['estado']==='RESERVED')tfPromote($db,$b['horario_id'],$b['fecha']);return tfDescribe($db,$id);}
function tfWrite(mysqli $db,string $principal,int $person,array $r,bool $admin=false):array{if(!$admin)tfAllowed($db,$principal,$person);$key=(string)($r['request_key']??'');tfRequire(preg_match('/^[A-Za-z0-9:_-]{8,100}$/',$key),'IDEMPOTENCY_REQUIRED');$copy=$r;unset($copy['request_key']);ksort($copy);$hash=hash('sha256',json_encode($copy));return tfAtomic($db,function()use($db,$principal,$person,$r,$key,$hash){$old=tfQuery($db,'SELECT * FROM tf_requests WHERE principal=? AND request_key=?',[$principal,$key])[0]??null;if($old){tfRequire(hash_equals($old['request_hash'],$hash),'IDEMPOTENCY_CONFLICT',409);return json_decode($old['response'],true,32,JSON_THROW_ON_ERROR);}$action=$r['action']??'';
 if($action==='reserve')$booking=tfReserve($db,$person,(int)($r['horario_id']??0),(string)($r['fecha']??''),($r['accept_waitlist']??false)===true);
 elseif(in_array($action,['cancel','leave_waitlist'],true))$booking=tfCancel($db,$person,(int)($r['booking_id']??0),isset($r['version'])?(int)$r['version']:null);
 elseif($action==='reschedule'){$oldBooking=tfDescribe($db,(int)$r['booking_id']);tfRequire($oldBooking['persona_id']===$person&&$oldBooking['version']===(int)$r['version']&&$oldBooking['estado']==='RESERVED','STALE_ACTION',409);tfRequire($oldBooking['horario_id']!==(int)$r['horario_id']||$oldBooking['fecha']!==(string)$r['fecha'],'TARGET_UNAVAILABLE');$booking=tfReserve($db,$person,(int)$r['horario_id'],(string)$r['fecha'],false,$oldBooking['id']);tfCancel($db,$person,$oldBooking['id'],$oldBooking['version']);}
 else throw new WebError('UNKNOWN_ACTION');$out=['ok'=>true,'booking'=>$booking];tfQuery($db,'INSERT INTO tf_requests VALUES(?,?,?,?)',[$principal,$key,$hash,json_encode($out)]);return $out;});}
require_once __DIR__.'/offers.php';
